use bend2_lsp::analysis::{self, CompletionKind, DocumentSnapshot, Revision};

fn main() {
    for source in ["", "def constant() -> U32:\n  0\n", "def wrap(_: U32) -> U32:\n  0\n"] {
        let snapshot = DocumentSnapshot::new(Revision(1), source.to_owned());
        assert_eq!(analysis::scoped_completion_items(&snapshot, source.len(), "parameter"), []);
        assert_eq!(analysis::scoped_completion_items(&snapshot, source.len(), "_"), []);
    }
    let function = "def wrap(parameter: U32) -> U32:\n  parameter";
    let eof = DocumentSnapshot::new(Revision(2), function.to_owned());
    let completed = analysis::scoped_completion_items(&eof, function.len(), "parameter");
    assert_eq!(completed.iter().map(|item| (item.label.as_str(), item.kind)).collect::<Vec<_>>(), [("parameter", CompletionKind::Variable)]);

    let mut source = format!("{function}\n");
    for index in 0..80 {
        source.push_str(&format!("def later_{index}() -> U32:\n  {index}\n"));
    }
    let snapshot = DocumentSnapshot::new(Revision(3), source.clone());
    let binding = &snapshot.syntax.bindings()[0];
    let body = source.find("\n  parameter").map_or(0, |offset| offset + 3);
    let completed = analysis::scoped_completion_items(&snapshot, body, "parameter");
    assert_eq!(completed.iter().map(|item| (item.label.as_str(), item.kind)).collect::<Vec<_>>(), [("parameter", CompletionKind::Variable)]);
    assert_eq!(analysis::scoped_completion_items(&snapshot, binding.scope.end, "parameter"), []);
    let outside = source.find("def later_79").map_or(0, |offset| offset + 4);
    let completed = analysis::scoped_completion_items(&snapshot, outside, "later_79");
    assert_eq!(completed.iter().map(|item| (item.label.as_str(), item.kind)).collect::<Vec<_>>(), [("later_79", CompletionKind::Function)]);
    assert_eq!(analysis::scoped_completion_items(&snapshot, outside, "parameter"), []);
    println!("local-index API smoke passed: empty/anonymous locals, singleton parameter, EOF completion, half-open scope end, and late global names beyond local index domain");
}
